const list=document.querySelector('#topic-list');
const count=document.querySelector('#topic-count');
const topicForm=document.querySelector('#topic-form');
const topicStatus=document.querySelector('#topic-form-status');
const dialog=document.querySelector('#topic-dialog');
const replyForm=document.querySelector('#reply-form');
const replyStatus=document.querySelector('#reply-form-status');
let activeCategory='全部';
let activeTopic=null;
const dateText=value=>new Date(value).toLocaleString('zh-CN',{year:'numeric',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'});
const node=(tag,className,text)=>{const el=document.createElement(tag);if(className)el.className=className;if(text!==undefined)el.textContent=text;return el};
async function request(path,options={}){const r=await fetch(path,{...options,headers:{'content-type':'application/json',...(options.headers||{})}});let body;try{body=await r.json()}catch{throw Error('服务暂时不可用，请稍后再试。')}if(!r.ok)throw Error(body.error||'操作失败，请稍后再试。');return body}
async function loadTopics(){list.replaceChildren(node('p','topic-empty','正在读取话题…'));try{const data=await request(`/api/topics?category=${encodeURIComponent(activeCategory)}`);count.textContent=`${data.items.length} 个话题`;if(!data.items.length){list.replaceChildren(node('p','topic-empty','这里还没有话题。你可以发起第一个讨论。'));return}list.replaceChildren(...data.items.map(topic=>{const row=node('article','topic-row');row.append(node('div','topic-avatar',topic.nickname.slice(0,1).toUpperCase()));const main=node('div','topic-main');const title=node('button','topic-title',topic.title);title.type='button';title.addEventListener('click',()=>openTopic(topic.id));const meta=node('div','topic-meta');meta.append(node('span','topic-category',topic.category),document.createTextNode(`${topic.nickname} · ${dateText(topic.created_at)}`));main.append(title,meta);row.append(main,node('span','reply-pill',String(topic.reply_count)));return row}))}catch(e){count.textContent='读取失败';list.replaceChildren(node('p','topic-empty',e.message))}}
async function openTopic(id){try{const {topic,replies}=await request(`/api/topics/${id}`);activeTopic=id;document.querySelector('#dialog-category').textContent=topic.category;document.querySelector('#dialog-title').textContent=topic.title;document.querySelector('#dialog-meta').textContent=`${topic.nickname} · ${dateText(topic.created_at)}`;document.querySelector('#dialog-body').textContent=topic.body;document.querySelector('#reply-count').textContent=`${replies.length} 条回复`;document.querySelector('#reply-list').replaceChildren(...replies.map(reply=>{const item=node('article','reply-item');const strong=node('strong',null,reply.nickname);const time=node('time',null,dateText(reply.created_at));const p=node('p',null,reply.body);item.append(strong,time,p);return item}));replyStatus.textContent='';if(!dialog.open)dialog.showModal()}catch(e){alert(e.message)}}
document.querySelectorAll('[data-topic-filter]').forEach(button=>button.addEventListener('click',()=>{activeCategory=button.dataset.topicFilter;document.querySelectorAll('[data-topic-filter]').forEach(b=>b.classList.toggle('active',b===button));loadTopics()}));
topicForm.addEventListener('submit',async e=>{e.preventDefault();topicStatus.textContent='正在发布…';topicStatus.className='form-status';const values=Object.fromEntries(new FormData(topicForm));try{const data=await request('/api/topics',{method:'POST',body:JSON.stringify(values)});topicForm.reset();topicStatus.textContent='发布成功';topicStatus.classList.add('ok');activeCategory='全部';document.querySelectorAll('[data-topic-filter]').forEach(b=>b.classList.toggle('active',b.dataset.topicFilter==='全部'));await loadTopics();await openTopic(data.id)}catch(err){topicStatus.textContent=err.message}});
replyForm.addEventListener('submit',async e=>{e.preventDefault();if(!activeTopic)return;replyStatus.textContent='正在发送…';replyStatus.className='form-status';const values=Object.fromEntries(new FormData(replyForm));try{await request(`/api/topics/${activeTopic}/replies`,{method:'POST',body:JSON.stringify(values)});replyForm.reset();replyStatus.textContent='回复成功';replyStatus.classList.add('ok');await openTopic(activeTopic);await loadTopics()}catch(err){replyStatus.textContent=err.message}});
document.querySelector('#dialog-close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});loadTopics();
